mapper.select:
SELECT DATE_FORMAT(pa.created_at,'%Y-%m-%d') AS date,COUNT(*) AS attempts,COUNT(DISTINCT pa.exercise_id) AS exercises
FROM practice_attempts pa WHERE pa.student_id=#{studentId} 
GROUP BY DATE_FORMAT(pa.created_at,'%Y-%m-%d') ORDER BY DATE_FORMAT(pa.created_at,'%Y-%m-%d')

SELECT pa.attempt_id AS attemptId,pa.exercise_id AS exerciseId,e.title,e.category_id AS categoryId,c.name AS categoryName,
  pa.attempt_type AS attemptType,DATE_FORMAT(pa.created_at,'%Y-%m-%d %H:%i') AS practicedAt
FROM practice_attempts pa JOIN exercises e ON e.exercise_id=pa.exercise_id JOIN practice_categories c ON c.category_id=e.category_id
WHERE pa.student_id=#{studentId} 
ORDER BY pa.created_at DESC,pa.attempt_id DESC LIMIT #{limit}
